function getDefaultRunQueueIds(activePage: string) {
  if (activePage.includes("Payment")) return ["payments"];
  if (activePage.includes("Inquiry") || activePage.includes("Source")) return ["inquiries"];
  if (activePage.includes("Refill") || activePage.includes("Restock") || activePage.includes("Inactive")) return ["repeat"];
  if (activePage.includes("Order") || activePage.includes("Delivery") || activePage.includes("Reviews")) return ["orders"];
  if (activePage.includes("Automation") || activePage.includes("Reports") || activePage.includes("Summary")) return ["reports"];
  return ["today"];
}

function RunQueuePanel({
  activePage,
  onClose,
  onRun,
}: {
  activePage: string;
  onClose: () => void;
  onRun: (queueIds: string[], channels: WorkflowChannel[]) => void;
}) {
  const [selectedQueues, setSelectedQueues] = useState<string[]>(() => getDefaultRunQueueIds(activePage));
  const [selectedChannels, setSelectedChannels] = useState<WorkflowChannel[]>(["Manual Copy", "WhatsApp", "Instagram DM", "Meta Inbox", "Facebook Messenger", "Email"]);

  function toggleQueue(id: string) {
    setSelectedQueues((current) =>
      current.includes(id) ? current.filter((item) => item !== id) : [...current, id],
    );
  }

  function toggleChannel(channel: WorkflowChannel) {
    setSelectedChannels((current) =>
      current.includes(channel) ? current.filter((item) => item !== channel) : [...current, channel],
    );
  }

  return (
    <div className="queue-run-backdrop" role="presentation">
      <section className="queue-run-panel glass-card" role="dialog" aria-modal="true">
        <div className="queue-run-header">
          <div>
            <span>Run the queue</span>
            <h2>Choose what Altynx should prepare now</h2>
            <p>
              Select the queues and channels that should be prepared from the current recovery context.
              Nothing leaves the workspace automatically; the action status is logged for review.
            </p>
          </div>
          <button className="secondary-btn" type="button" onClick={onClose}>
            Close
          </button>
        </div>

        <div className="queue-run-grid">
          {runQueueOptions.map((option) => (
            <button
              key={option.id}
              type="button"
              className={`queue-run-option ${selectedQueues.includes(option.id) ? "selected" : ""}`}
              onClick={() => toggleQueue(option.id)}
            >
              <strong>{option.label}</strong>
              <p>{option.description}</p>
              <small>{option.channels.join(" • ")}</small>
            </button>
          ))}
        </div>

        <div className="queue-run-channel-card">
          <h3>Prepare channel actions for</h3>
          <div className="queue-run-channels">
            {workflowChannels.map((channel) => (
              <button
                key={channel}
                type="button"
                className={selectedChannels.includes(channel) ? "selected" : ""}
                onClick={() => toggleChannel(channel)}
              >
                {channel}
              </button>
            ))}
          </div>
        </div>

        <div className="queue-run-actions">
          <button className="secondary-btn" type="button" onClick={onClose}>
            Cancel
          </button>
          <button
            className="primary-btn"
            type="button"
            disabled={selectedQueues.length === 0 || selectedChannels.length === 0}
            onClick={() => onRun(selectedQueues, selectedChannels)}
          >
            Run selected queues
          </button>
        </div>
      </section>
    </div>
  );
}


type WalkthroughPlacement = "auto" | "right" | "left" | "bottom" | "top" | "center";

type WalkthroughStep = {
  title: string;
  page: string;
  selector: string;
  message: string;
  cta?: string;
  actionLabel?: string;
  actionSelector?: string;
  actionEvent?: string;
  actionNavigatePage?: string;
  waitForUserClickSelector?: string;
  hideNext?: boolean;
  placement?: WalkthroughPlacement;
};

type WalkthroughRect = {
  top: number;
  left: number;
  width: number;
  height: number;
};

type TourCardCandidate = {
  placement: Exclude<WalkthroughPlacement, "auto"> | "corner";
  top: number;
  left: number;
  width: number;
  height: number;
  fits: boolean;
  overlap: number;
};

function clampNumber(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

