function getNextTourPage(currentPage: string, pages: string[]) {
  if (pages.length === 0) return null;

  const currentIndex = pages.findIndex((page) => page === currentPage);
  if (currentIndex < 0) return pages[0];

  return pages[(currentIndex + 1) % pages.length] ?? null;
}

function getGenericRecordSelector(page: string) {
  const selectors: Record<string, string> = {
    "Recovery Threads": ".recovery-thread-list-shell, .thread-list-card, .recovery-page",
    "Team Load": ".team-load-grid, .team-load-card, .recovery-page",
    "Automation Health": ".automation-health-page, .automation-health-record, .panel-card",
    "Revenue Leak Reports": ".revenue-leak-page, .leak-report-card, .panel-card",
    "Monthly Summary": ".monthly-summary-page, .monthly-summary-card, .panel-card",
    "Brand Settings": ".setup-page, .workspace-personalization-card, .setup-card-list, .panel-card",
    "Team Users": ".setup-page, .setup-card-list, .team-user-card, .panel-card",
    "Tags & Stages": ".setup-page, .setup-card-list, .tag-chip, .panel-card",
    "Templates": ".setup-page, .setup-card-list, .template-card, .panel-card",
  };

  return selectors[page] ?? ".recovery-row, .action-task, .thread-list-card, .panel-card, .glass-card";
}

function buildGenericWalkthroughSteps(page: string): WalkthroughStep[] {
  const copy = pageTourCopy[page] ?? {
    purpose: `${page} is a focused recovery surface inside Altynx.`,
    records: "Open records to review context, risk, owner, status, and next action.",
    actions: "Use the page controls to search, sync, run queues, export, or capture work.",
    finish: "Use this page when the matching recovery work needs attention.",
  };

  return [
    {
      title: `${page}: what this page does`,
      page,
      selector: '[data-tour-target="page-title"]',
      message: copy.purpose,
    },
    {
      title: `${page}: search and jump`,
      page,
      selector: '[data-tour-target="workspace-search"]',
      message:
        "Use this search to jump to pages, buyers, records, channels, source names, queues, payment cases, Meta/Facebook messages, restocks, reviews, reports, and setup records without leaving the flow.",
    },
    {
      title: `${page}: page controls`,
      page,
      selector: '[data-tour-target="quick-actions"]',
      message: copy.actions,
    },
    {
      title: `${page}: work the records`,
      page,
      selector: getGenericRecordSelector(page),
      message: copy.records,
    },
    {
      title: `${page}: run or sync the work`,
      page,
      selector: ".workspace-run-queue-btn, .workspace-sync-btn, [data-tour-target='quick-actions']",
      message:
        "Run the Queue prepares the selected queues and channels for review. Sync to Automations logs the action status so connected workflows can respond without turning Altynx into an automation builder.",
    },
    {
      title: `${page}: when to use it`,
      page,
      selector: ".content, .recovery-page, .setup-page",
      message: copy.finish,
    },
  ];
}

