  const pageOrder = pages.length > 0 ? pages : sidebarGroups.flatMap((group) => group.items);
  const [tourPage, setTourPage] = useState(activePage);
  const [stepIndex, setStepIndex] = useState(0);
  const [spotlightRect, setSpotlightRect] = useState<WalkthroughRect | null>(null);
